import React from "react";
import Link from "next/link";
import { ChevronRight, Home } from "lucide-react";

export interface BreadcrumbItem {
  label: string;
  href?: string;
}

export default function Breadcrumbs({ items }: { items: BreadcrumbItem[] }) {
  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      {
        "@type": "ListItem",
        position: 1,
        name: "Главная",
        item: "/",
      },
      ...items.map((item, idx) => ({
        "@type": "ListItem",
        position: idx + 2,
        name: item.label,
        ...(item.href ? { item: item.href } : {}),
      })),
    ],
  };

  return (
    <nav aria-label="Хлебные крошки" className="mb-6">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <ol className="flex flex-wrap items-center gap-1.5 text-xs text-[#525D59]">
        <li>
          <Link
            href="/"
            className="inline-flex items-center gap-1 hover:text-[#164E43] transition"
          >
            <Home className="h-3.5 w-3.5" />
            <span>Главная</span>
          </Link>
        </li>
        {items.map((item, idx) => (
          <li key={idx} className="inline-flex items-center gap-1.5">
            <ChevronRight className="h-3.5 w-3.5 text-[#848E8A]" />
            {item.href ? (
              <Link
                href={item.href}
                className="hover:text-[#164E43] transition"
              >
                {item.label}
              </Link>
            ) : (
              <span className="font-medium text-[#14221E]" aria-current="page">
                {item.label}
              </span>
            )}
          </li>
        ))}
      </ol>
    </nav>
  );
}
