export interface DemoStore {
  categories: CategoryRecord[];
  services: ServiceRecord[];
  doctors: DoctorRecord[];
  appointments: AppointmentRecord[];
  reviews: ReviewRecord[];
  gallery: GalleryRecord[];
  promotions: PromotionRecord[];
  articles: ArticleRecord[];
  settings: SiteSettingsData;
  auditLogs: AuditLogRecord[];
}

const globalForDemo = globalThis as typeof globalThis & {
  __kvalitetDemoStore?: DemoStore;
};

function createInitialDemoStore(): DemoStore {
  const now = new Date();
  return {
    categories: INITIAL_CATEGORIES.map((c, idx) => ({
      id: idx + 1,
      ...c,
      isPublished: true,
      updatedAt: now,
    })),
    services: INITIAL_SERVICES.map((s, idx) => ({
      id: idx + 1,
      slug: s.slug,
      categorySlug: s.categorySlug,
      title: s.title,
      shortDescription: s.shortDescription,
      description: s.description,
      indications: s.indications,
      consultationFlow: s.consultationFlow,
      preparation: s.preparation,
      contraindications: s.contraindications,
      faqJson: JSON.stringify(s.faq),
      priceType: s.priceType,
      priceValue: s.priceValue,
      priceMax: s.priceMax,
      priceDisplay: s.priceDisplay,
      isPricedItem: s.isPricedItem,
      isPopular: s.isPopular,
      isPublished: true,
      imageUrl: s.imageUrl,
      sortOrder: s.sortOrder,
      updatedAt: now,
    })),
    doctors: [],
    appointments: [],
    reviews: [],
    gallery: INITIAL_GALLERY_ITEMS.map((g, idx) => ({
      id: idx + 1,
      ...g,
      isPublished: true,
      createdAt: now,
    })),
    promotions: [],
    articles: INITIAL_ARTICLES.map((a, idx) => ({
      id: idx + 1,
      slug: a.slug,
      title: a.title,
      category: a.category,
      excerpt: a.excerpt,
      content: a.content,
      coverImage: a.coverImage,
      seoTitle: a.seoTitle,
      seoDescription: a.seoDescription,
      relatedServiceSlugsJson: JSON.stringify(a.relatedServiceSlugs),
      isPublished: true,
      publishedAt: now,
      updatedAt: now,
    })),
    settings: { ...DEFAULT_SITE_SETTINGS },
    auditLogs: [
      {
        id: 1,
        action: "init_demo",
        entityType: "system",
        entityId: "main",
        details: "Демо-сайт стоматологии «Квалитет» запущен в автономном режиме (без БД)",
        createdAt: now,
      },
    ],
  };
}

export function getDemoStore(): DemoStore {
  if (!globalForDemo.__kvalitetDemoStore) {
    globalForDemo.__kvalitetDemoStore = createInitialDemoStore();
  }
  return globalForDemo.__kvalitetDemoStore;
}

export async function ensureDatabaseReady(): Promise<void> {
  getDemoStore();
}

export async function getSiteSettings(): Promise<SiteSettingsData> {
  return getDemoStore().settings;
}

export async function getCategories(includeUnpublished = false) {
  const all = [...getDemoStore().categories].sort(
    (a, b) => a.sortOrder - b.sortOrder
  );
  if (includeUnpublished) return all;
  return all.filter((c) => c.isPublished);
}

export async function getCategoryBySlug(slug: string) {
  const cats = await getCategories(true);
  return cats.find((c) => c.slug === slug) ?? null;
}

export async function getServices(includeUnpublished = false) {
  const all = [...getDemoStore().services].sort(
    (a, b) => a.sortOrder - b.sortOrder || a.id - b.id
  );
  if (includeUnpublished) return all;
  return all.filter((s) => s.isPublished);
}

export async function getServiceBySlug(slug: string) {
  const all = await getServices(true);
  return all.find((s) => s.slug === slug) ?? null;
}

