export async function getAppointments() {
  return [...getDemoStore().appointments].sort(
    (a, b) => b.createdAt.getTime() - a.createdAt.getTime()
  );
}

export async function logAdminAction(
  action: string,
  entityType: string,
  entityId = "",
  details = ""
) {
  const store = getDemoStore();
  const nextId =
    store.auditLogs.reduce((max, item) => Math.max(max, item.id), 0) + 1;
  store.auditLogs.unshift({
    id: nextId,
    action,
    entityType,
    entityId: String(entityId),
    details,
    createdAt: new Date(),
  });
}

export async function getAdminAuditLogs(limit = 30) {
  return getDemoStore().auditLogs.slice(0, limit);
}
